function hb_log($m){ if(class_exists('WP_CLI')) WP_CLI::log($m); else echo $m.PHP_EOL; }
function hb_warn($m){ if(class_exists('WP_CLI')) WP_CLI::warning($m); else fwrite(STDERR,$m.PHP_EOL); }
function hb_success($m){ if(class_exists('WP_CLI')) WP_CLI::success($m); else echo "OK: ".$m.PHP_EOL; }

function hb_norm($s){
    $s = html_entity_decode((string)$s, ENT_QUOTES|ENT_HTML5, 'UTF-8');
    $s = mb_strtoupper($s,'UTF-8');
    if (function_exists('remove_accents')) $s = remove_accents($s);
    $s = preg_replace('/[^A-Z0-9]+/u',' ', $s);
    return trim(preg_replace('/\s+/u',' ', $s));
}

function hb_get($url, $timeout=30){
    $r = wp_remote_get($url,[
        'timeout'=>$timeout,'redirection'=>5,'user-agent'=>HB_UA,
        'headers'=>['Accept'=>'text/html,application/xhtml+xml','Accept-Language'=>'en-US,en;q=0.9']
    ]);
    if(is_wp_error($r)) throw new RuntimeException($r->get_error_message());
    $code=(int)wp_remote_retrieve_response_code($r);
    if($code<200||$code>=400) throw new RuntimeException("HTTP {$code} for {$url}");
    return (string)wp_remote_retrieve_body($r);
}

function hb_abs($url){
    $url=html_entity_decode(trim((string)$url),ENT_QUOTES|ENT_HTML5,'UTF-8');
    if($url==='') return '';
    if(str_starts_with($url,'//')) return 'https:'.$url;
    if(str_starts_with($url,'/')) return HB_BASE.$url;
    return $url;
}

function hb_product_links(){
    $found=[];
    $empty=0;
    for($page=1;$page<=20;$page++){
        $url = $page===1 ? HB_MANUFACTURER : rtrim(HB_MANUFACTURER,'/').'/page/'.$page.'/';
        try { $html=hb_get($url); } catch(Throwable $e){
            if($page===1) throw $e;
            break;
        }
        preg_match_all('~href=["\']([^"\']+/en/product/[^"\']+)["\']~i',$html,$m);
        $before=count($found);
        foreach(($m[1]??[]) as $u){
            $u=hb_abs($u);
            if(!str_starts_with($u,HB_BASE.'/en/product/')) continue;
            $found[rtrim($u,'/').'/']=true;
        }
        if(count($found)===$before){ $empty++; if($empty>=2) break; } else $empty=0;
    }
    return array_keys($found);
}

function hb_dom($html){
    libxml_use_internal_errors(true);
    $dom=new DOMDocument();
    @$dom->loadHTML('<?xml encoding="utf-8" ?>'.$html);
    return $dom;
}

function hb_title($dom){
    $xp=new DOMXPath($dom);
    foreach(['//h1[contains(@class,"product_title")]','//h1[1]'] as $q){
        $n=$xp->query($q);
        if($n&&$n->length){
            $t=trim(preg_replace('/\s+/u',' ',$n->item(0)->textContent));
            if($t!=='') return $t;
        }
    }
    return '';
}

function hb_attrs($dom){
    $xp=new DOMXPath($dom); $out=[];
    $rows=$xp->query('//table[contains(@class,"woocommerce-product-attributes")]//tr | //table//tr');
    if(!$rows) return $out;
    foreach($rows as $tr){
        $ths=$xp->query('.//th',$tr); $tds=$xp->query('.//td',$tr);
        if(!$ths||!$ths->length||!$tds||!$tds->length) continue;
        $k=trim(preg_replace('/\s+/u',' ',$ths->item(0)->textContent));
        $v=trim(preg_replace('/\s+/u',' ',$tds->item(0)->textContent));
        if($k!==''&&$v!=='') $out[$k]=$v;
    }
    return $out;
}

function hb_images($dom){
    $xp=new DOMXPath($dom); $urls=[];
    foreach([
        '//div[contains(@class,"woocommerce-product-gallery")]//img',
        '//figure[contains(@class,"woocommerce-product-gallery")]//img',
        '//meta[@property="og:image"]'
    ] as $q){
        $nodes=$xp->query($q);
        if(!$nodes) continue;
        foreach($nodes as $node){
            $raw='';
            if(strtolower($node->nodeName)==='meta') $raw=$node->getAttribute('content');
            else{
                foreach(['data-large_image','data-src','src'] as $a){
                    $v=trim($node->getAttribute($a)); if($v!==''){ $raw=$v; break; }
                }
            }
            $raw=hb_abs($raw); if($raw==='') continue;
            if(!preg_match('~^https?://~i',$raw)) continue;
            if(preg_match('~(?:logo|icon|avatar|payment|flag)~i',$raw)) continue;
            $urls[$raw]=true;
        }
    }
    return array_slice(array_keys($urls),0,6);
}

function hb_match($title,$catalog){
    $nt=hb_norm($title);
    $best=null; $best_len=0;
    foreach($catalog as $row){
        $sku=hb_norm($row['sku']??'');
        if($sku!=='' && preg_match('/(?:^| )'.preg_quote($sku,'/').'(?: |$)/',$nt)){
            return $row;
        }
    }
    foreach($catalog as $row){
        $model=hb_norm($row['model']??'');
        if(strlen($model)<4) continue;
        if(str_contains($nt,$model) && strlen($model)>$best_len){
            $best=$row; $best_len=strlen($model);
        }
    }
    return $best;
}

function hb_type($title,$attrs){
    $txt=hb_norm($title.' '.json_encode($attrs,JSON_UNESCAPED_UNICODE));
    $fire = str_contains($txt,'ELECTRIC') ? 'électrique' : 'bioéthanol';
    if(str_contains($txt,'SIDEBOARD')) $base='Buffet';
    elseif(str_contains($txt,'TV STAND')||str_contains($txt,'TV CABINET')||str_contains($txt,'RTV')) $base='Meuble TV';
    elseif(str_contains($txt,'WALL UNIT')) $base='Ensemble mural';
    elseif(str_contains($txt,'CABINET')) $base='Meuble de rangement';
    else $base='Meuble';
    return [$base,$fire];
}

function hb_find_attr($attrs,$needle){
    foreach($attrs as $k=>$v) if(str_contains(mb_strtolower($k,'UTF-8'),mb_strtolower($needle,'UTF-8'))) return $v;
    return '';
}

function hb_description($row,$attrs,$type,$fire){
    $model=esc_html($row['model']);
    $sku=esc_html($row['sku']);
    $color=esc_html((string)($row['color']??''));
    $h=esc_html(hb_find_attr($attrs,'Height'));
    $w=esc_html(hb_find_attr($attrs,'Width'));
    $d=esc_html(hb_find_attr($attrs,'Depth'));
    $weight=esc_html(hb_find_attr($attrs,'Weight'));
    $warranty=esc_html(hb_find_attr($attrs,'Warranty'));
    $html="<p><strong>{$type} {$model} avec cheminée {$fire}</strong>, sélectionné dans la gamme ASM Meble.</p><ul>";
    $html.="<li><strong>Référence ASM :</strong> {$sku}</li>";
    if($color!=='') $html.="<li><strong>Finition :</strong> ".nl2br($color)."</li>";
    if($w!=='') $html.="<li><strong>Largeur :</strong> {$w}</li>";
    if($h!=='') $html.="<li><strong>Hauteur :</strong> {$h}</li>";
    if($d!=='') $html.="<li><strong>Profondeur :</strong> {$d}</li>";
    if($weight!=='') $html.="<li><strong>Poids :</strong> {$weight}</li>";
    if($warranty!=='') $html.="<li><strong>Garantie :</strong> {$warranty}</li>";
    $html.="</ul><p>La cheminée s’intègre directement au meuble pour créer un ensemble décoratif prêt à installer. Vérifiez toujours les consignes d’utilisation du foyer avant la première utilisation.</p>";
    return $html;
}

function hb_term($name,$tax,$slug=''){
    $exists=term_exists($name,$tax);
    if(is_array($exists)) return (int)$exists['term_id'];
    if(is_int($exists)) return $exists;
    $args=[]; if($slug!=='') $args['slug']=$slug;
    $r=wp_insert_term($name,$tax,$args);
    if(is_wp_error($r)) throw new RuntimeException($r->get_error_message());
    return (int)$r['term_id'];
}

function hb_sideload($urls,$post_id){
    global $skip_images;
    if($skip_images) return [];
    $ids=[];
    foreach($urls as $u){
        $id=media_sideload_image($u,$post_id,null,'id');
        if(is_wp_error($id)){ hb_warn("Image skipped: ".$id->get_error_message()); continue; }
        $ids[]=(int)$id;
    }
    return array_values(array_unique($ids));
}

hb_log('Heat Baltic ASM -> Decora Home');
hb_log('Pricing/model rows loaded: '.count($catalog));
hb_log('Rule: supplier price + 50 EUR, rounded upward to price ending in 9; customer shipping marker = 49 EUR.');
if($dry) hb_warn('DRY RUN: no WordPress writes.');

$shipping_class_id=hb_term('ASM 49 €','product_shipping_class','asm-49');
$cat_parent=hb_term('Meubles avec cheminée','product_cat','meubles-avec-cheminee');
$cat_bio=hb_term('Cheminée bioéthanol','product_cat','cheminee-bioethanol');
$cat_ele=hb_term('Cheminée électrique','product_cat','cheminee-electrique');

$links=hb_product_links();
hb_log('Heat Baltic product links found: '.count($links));

$matched=0;$created=0;$updated=0;$unmatched=0;$errors=0;$i=0;
foreach($links as $url){
    $i++;
    try{
        $html=hb_get($url);
        $dom=hb_dom($html);
        $title=hb_title($dom);
        if($title===''||!preg_match('/^ASM\b/i',$title)) continue;
        $row=hb_match($title,$catalog);
        if(!$row){ $unmatched++; hb_warn("UNMATCHED: {$title}"); continue; }
        $matched++;
        $attrs=hb_attrs($dom);
        [$base,$fire]=hb_type($title,$attrs);
        $name=$base.' '.$row['model'].' avec cheminée '.$fire;
        $sku=(string)$row['sku'];
        $sale=(float)$row['sale'];
        $existing=wc_get_product_id_by_sku($sku);
        $is_new=!$existing;

        hb_log(($is_new?'CREATE':'UPDATE')." {$sku} | {$name} | {$sale} € + 49 € livraison");
        if($dry) continue;

        $p=$existing?wc_get_product($existing):new WC_Product_Simple();
        if(!$p) throw new RuntimeException("Cannot create WC product {$sku}");
        $p->set_name($name);
        if($is_new){ $p->set_sku($sku); $p->set_status('draft'); }
        $p->set_regular_price(wc_format_decimal($sale,2));
        $p->set_price(wc_format_decimal($sale,2));
        $p->set_manage_stock(false);
        $p->set_stock_status('instock');
        $p->set_shipping_class_id($shipping_class_id);
        $p->set_description(hb_description($row,$attrs,$base,$fire));
        $p->set_short_description('<strong>ASM Meble</strong> · Réf. '.esc_html($sku).' · Livraison 49 €');
        $p->set_category_ids([$cat_parent, $fire==='électrique'?$cat_ele:$cat_bio]);

        $w=hb_find_attr($attrs,'Width'); $h=hb_find_attr($attrs,'Height'); $d=hb_find_attr($attrs,'Depth'); $weight=hb_find_attr($attrs,'Weight');
        if(preg_match('/([\d.,]+)/',$w,$m)) $p->set_width(wc_format_decimal(str_replace(',','.',$m[1])/10,1));
        if(preg_match('/([\d.,]+)/',$h,$m)) $p->set_height(wc_format_decimal(str_replace(',','.',$m[1])/10,1));
        if(preg_match('/([\d.,]+)/',$d,$m)) $p->set_length(wc_format_decimal(str_replace(',','.',$m[1])/10,1));
        if(preg_match('/([\d.,]+)/',$weight,$m)) $p->set_weight(wc_format_decimal(str_replace(',','.',$m[1]),2));

        $pid=$p->save();
        update_post_meta($pid,'_asm_source_url',esc_url_raw($url));
        update_post_meta($pid,'_asm_supplier','ASM Meble');
        update_post_meta($pid,'_asm_customer_shipping','49');
        update_post_meta($pid,'_asm_price_rule','supplier_plus_50_rounded_to_9');
        update_post_meta($pid,'_asm_source_content','Heat Baltic');

        $images=hb_images($dom);
        if($images){
            $ids=hb_sideload($images,$pid);
            if($ids){
                $p=wc_get_product($pid);
                if(!$p->get_image_id()) $p->set_image_id($ids[0]);
                if(count($ids)>1 && !$p->get_gallery_image_ids()) $p->set_gallery_image_ids(array_slice($ids,1));
                $p->save();
            }
        }

        if($is_new)$created++;else$updated++;
    }catch(Throwable $e){
        $errors++; hb_warn("FAILED {$url}: ".$e->getMessage());
    }
    if($i%10===0) hb_log("Progress {$i}/".count($links)." | matched {$matched} | created {$created} | updated {$updated} | unmatched {$unmatched}");
}

hb_log('');
hb_log('=== HEAT BALTIC ASM IMPORT SUMMARY ===');
hb_log('Links scanned: '.count($links));
hb_log("Matched: {$matched}");
hb_log("Created: {$created}");
hb_log("Updated: {$updated}");
hb_log("Unmatched: {$unmatched}");
hb_log("Errors: {$errors}");
hb_success($dry ? 'Dry run completed.' : 'Import completed. New products are drafts. Shipping class asm-49 and 49 EUR marker applied.');
